import os

# ─── Server ──────────────────────────────────────────────────────────────────

SERVER_HOST = "0.0.0.0"
SERVER_PORT = int(os.environ.get("IOT_AUTH_PORT", "5000"))

# TLS certificate paths (generated by certs/setup_certs.sh)
TLS_CERT = os.path.join(os.path.dirname(__file__), "..", "certs", "server.crt")
TLS_KEY  = os.path.join(os.path.dirname(__file__), "..", "certs", "server.key")

# ─── Device Registry ─────────────────────────────────────────────────────────

# Pre-shared HMAC keys per device. Production deployments must set a unique
# secret outside source control. The fallback exists only so that the
# reproducible trace experiment and regression tests run from a clean clone.
DEVELOPMENT_DEVICE_KEY = "development-only-change-before-deploy-2026"
DEVICE_KEYS = {
    "esp32-lab-01": os.environ.get(
        "IOT_AUTH_ESP32_LAB_01_KEY",
        DEVELOPMENT_DEVICE_KEY,
    ),
}

# ─── Authentication Parameters ───────────────────────────────────────────────

# Sliding window size for score averaging (Equation 3 in the paper)
WINDOW_SIZE = 5

# Suspicion threshold (theta_s) - device becomes Suspect below this
SUSPICION_THRESHOLD = 0.75

# Challenge threshold (theta_c) - triggers cryptographic challenge
CHALLENGE_THRESHOLD = 0.45

# Number of consecutive suspect cycles before auto-challenge
SUSPECT_PATIENCE = 3

# Challenge response timeout in seconds
CHALLENGE_TIMEOUT_SEC = 10.0

# Number of failed challenges before Rejected state
MAX_CHALLENGE_FAILURES = 3

# Post-verification context re-enrollment. When a device passes a challenge
# that was issued while it reported a new, reachable network context (BSSID,
# channel, or resolvers), the next sample that confirms the same context
# becomes the new baseline. A device that returns to its previous context
# keeps its previous baseline. Set to False to require operator re-enrollment.
REENROLL_AFTER_VERIFICATION = True

# ─── Telemetry Feature Weights (Equation 1 in the paper) ────────────────────

# Weights for each normalized telemetry feature (w_i)
FEATURE_WEIGHTS = {
    "internet_state": 0.15,
    "rssi_stability": 0.10,
    "bssid_consistency": 0.14,
    "channel_consistency": 0.10,
    "dns_consistency": 0.12,
    "heap_stability": 0.03,
    "latency_stability": 0.06,
    "sequence_continuity": 0.15,
    "uptime_continuity": 0.15,
}

# ─── Baseline Thresholds ────────────────────────────────────────────────────

# RSSI variation tolerance (dBm) - fluctuations within this range are normal
RSSI_TOLERANCE = 15.0

# Latency variation tolerance (ms)
LATENCY_TOLERANCE = 200.0

# Heap variation tolerance (bytes)
HEAP_TOLERANCE = 5000

# Maximum acceptable sequence gap
MAX_SEQ_GAP = 5

# ─── Logging ─────────────────────────────────────────────────────────────────

# Directory for telemetry CSV logs
LOG_DIR = os.path.join(os.path.dirname(__file__), "..", "datasets")

# Server-side telemetry log filename format
TELEMETRY_LOG_FMT = "telemetry_{device_id}_{timestamp}.csv"

# Authentication event log
AUTH_LOG = os.path.join(os.path.dirname(__file__), "..", "datasets", "auth_events.csv")

# Per-message decision log (score, smoothed score, state, and status for every
# accepted telemetry message)
DECISION_LOG = os.path.join(os.path.dirname(__file__), "..", "datasets", "decisions.csv")

# Optional file that stores accepted signed envelopes as JSON lines. Used only
# to obtain a genuinely signed message for the replay experiment.
ENVELOPE_CAPTURE = os.environ.get("IOT_AUTH_CAPTURE_ENVELOPES", "")

# ─── Data Collection ─────────────────────────────────────────────────────────

# Polling interval for server-side CSV logging (seconds)
LOG_POLL_INTERVAL_SEC = 2.0
